/* WatchList 등록 (7040) */
/* AdminWatchListMapper.selectCtgr */
SELECT A.AI_INPT_CTGR_ID, A.AI_INPT_CTGR_NM, A.AI_INPT_CTGR_TXT
  FROM CSPD102TI A
WHERE A.AI_INPT_CTGR_ID = #{aiInptCtgrId}

/* WatchList 등록 (7040) */
/* AdminWatchListMapper.selectNewCtgrCd */
SELECT 'CT'||SUBSTR('00000'||A.CTGR_CFCD,-5) AS CTGR_CFCD
FROM (
	SELECT '00000'||TO_NUMBER(REPLACE(MAX(CTGR_CFCD),'CT','')) + 1 AS CTGR_CFCD
	FROM CSPD102TI
) A

