/* WatchList 등록 (7040) */
/* AdminWatchListMapper.deleteCtgr */
UPDATE CSPD102TI SET
	AI_INPT_CTGR_YN = 'N',
	TRN_LOG_SRNO = #{trnLogSrno}
WHERE AI_INPT_CTGR_ID = #{aiInptCtgrId}

UPDATE CSPD102TI SET
	AI_INPT_CTGR_END_DTM = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
WHERE AI_INPT_CTGR_ID = #{aiInptCtgrId}

