/* WatchList 등록 (7040) */ /* AdminWatchListMapper.selectGrpList */ SELECT M.AI_INPT_CTGR_ID , M.AI_INPT_LIST_ID , M.AI_INPT_LIST_NM , T.AI_INPT_CTGR_NM , M.AI_INPT_LIST_DES_TXT , '['||T.AI_INPT_CTGR_NM||'] '||M.AI_INPT_LIST_NM AS CRLST FROM CSPD103TI M , CSPD102TI T WHERE 1 = 1 AND T.AI_INPT_CTGR_ID = M.AI_INPT_CTGR_ID
AND M.AI_INPT_CTGR_ID = #{aiInptCtgrId}
AND M.AI_INPT_LIST_YN = 'Y'
ORDER BY M.AI_INPT_LIST_NM
ORDER BY M.AI_INPT_LIST_NM DESC
ORDER BY TO_NUMBER(M.AI_INPT_CTGR_ID), TO_NUMBER(M.AI_INPT_LIST_ID)

/* WatchList 등록 (7040) */
/* AdminWatchListMapper.selectGrp */
SELECT AI_INPT_CTGR_ID, AI_INPT_LIST_ID, AI_INPT_LIST_NM, AI_INPT_LIST_DES_TXT
  FROM CSPD103TI
WHERE AI_INPT_CTGR_ID = #{aiInptCtgrId}
  AND AI_INPT_LIST_ID = #{aiInptListId}

/* WatchList 등록 (7040) */
/* AdminWatchListMapper.selectNewGrpCd */
SELECT NVL(MAX(TO_NUMBER(AI_INPT_LIST_ID)),0) + 1
FROM CSPD103TI

