/* WatchList 등록 (7040) */
/* AdminWatchListMapper.selectCont */
SELECT AI_INPT_LIST_ID, AI_INPT_RSPT_TXT_SRNO, AI_INPT_RSPT_TXT_DES_TXT, 
	AI_INPT_RSPT_TXT_YN, AI_INPT_RSPT_TXT_RGS_DTM, AI_INPT_RSPT_TXT_END_DTM, 
	AI_INPT_CTGR_ID, TRN_LOG_SRNO, LST_DB_CHG_ID, LST_DB_CHG_DTM
