WHERE AI_INPT_CTGR_ID = #{aiInptCtgrId}
  AND AI_INPT_LIST_ID = #{aiInptListId}
  AND AI_INPT_RSPT_TXT_SRNO = #{aiInptRsptTxtSrno}

